import{_ as t,o as l,c as n,j as a,a as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/72-寻找自己的安全型角色模式.md","filePath":"books/attached/72-寻找自己的安全型角色模式.md","lastUpdated":1794316978000}'),r={name:"books/attached/72-寻找自己的安全型角色模式.md"};function s(_,e,d,p,i,c){return l(),n("div",null,[...e[0]||(e[0]=[a("h3",{id:"寻找自己的安全型角色模式",tabindex:"-1"},[o("寻找自己的安全型角色模式 "),a("a",{class:"header-anchor",href:"#寻找自己的安全型角色模式","aria-label":'Permalink to "寻找自己的安全型角色模式"'},"​")],-1),a("p",null,"其实对安全感的触发一点都不难，只要多思考周围的安全型人群在亲密关系中是怎么做的，就能够实现。为了找到这种角色模式，一定要在心中回忆人生中经历过的各式各样的人，无论是过去还是现在。安全感不仅可能出现在亲子关系这种非常亲密的情况下，也有可能出现在你通过工作或朋友偶然认识的人身上。最重要的不在于这个人是谁，而在于他有着安全型依恋风格以及待人处事的安全行为模式。一旦你身边出现了一个或多个这样的人，就应该尝试着将他们与人相处的模式综合起来，形成一个综合的图式：包括他们说话的方式；在不同情形下的反应；他们的关注点和忽略点；在伴侣情绪低落时的行为方式；以及他们在生活与亲密关系之中的大体形象概括。比如下面这样：",-1),a("ul",null,[a("li",null,[a("p",null,"“当我与经理的意见不合时，我会非常直白地表达出来。他会对我的意见产生很大的兴趣，并且与我探讨这件事，而不是与我针锋相对。”")]),a("li",null,[a("p",null,"“我最好的朋友约翰（Jon）和妻子劳拉（Laura），总是鼓励对方去做自己喜欢的事。当劳拉决定离开律师事务所，投身于社会工作时，即使这意味着家中经济负担大大加重，约翰还是头一个向她表达了祝福。”")])],-1),a("p",null,"安全角色模式，类似和宠物相处？",-1),a("p",null,"苏珊娜·菲利普（Susannah phillips.)，是《共同治愈》（Healing together）一书的合作者之一，她在书中说道，我们与宠物的相处模式，能够为我们的亲密关系提供一些启发。即使我们的宠物有很多陋习，但我们还是会无私地宠爱着它们：它们会在半夜吵醒我们，会将我们心爱的东西弄坏，还需要我们无微不至地关注，将它们捧在手心。事实上，我们与宠物的相处模式，正是生活中安全型相处模式的绝佳范例。我们对于宠物的态度总是充满着安全感的，不会担心它们故意伤害。即使它们乱吃东西，或是把家里弄得一团糟，也不会过多责怪。依然会在回到家时给它们一个亲密的问候，即使在外面经历了糟糕的一天也不会迁怒它们，总之，我们会对宠物们，给予无条件的爱。",-1),a("p",null,"你可以将所想到的一切安全型榜样都整合起来，总结他们值得学习的品质。整合起来的内容，将成为你自己的安全角色榜样，而这也就是你要努力的方向。",-1)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
